import{_ as t}from"./chunks/api-multilingual-retrieval.CLcf2N7y.js";import{bQ as a,aL as d,u as n,G as o}from"./chunks/framework.igrrHzX3.js";const s="/knowledge/images/api-endpoints.svg",r="/knowledge/images/api-modules.svg",i="/knowledge/images/api-sequence-diagram-search.svg",c="/knowledge/images/api-sequence-diagram-ask.svg",k=JSON.parse('{"title":"API","description":"","frontmatter":{},"headers":[],"relativePath":"guides/components/api.md","filePath":"guides/components/api.md"}'),l={name:"guides/components/api.md"};function p(h,e,m,u,g,b){return d(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h1><p>The API <strong>serves the index</strong>. It turns a question into vectors, asks <a href="/knowledge/guides/components/qdrant.html">Qdrant</a> for the nearest chunks, and returns them, or hands them to an LLM and returns its answer.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>It is a <a href="https://fastapi.tiangolo.com/" target="_blank" rel="noreferrer">FastAPI</a> application served by <a href="https://www.uvicorn.org/" target="_blank" rel="noreferrer">uvicorn</a>, started with <code>python -m api.bin</code>.</p></div><p><img src="'+s+`" alt="Endpoints"></p><details class="details custom-block"><summary>Module Structure</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api/</span></span>
<span class="line"><span>├── bin.py              uvicorn.run(&quot;api.main:app&quot;, proxy_headers=True)</span></span>
<span class="line"><span>├── main.py             create_app(): lifespan checks, CORS, 503 handlers, router</span></span>
<span class="line"><span>├── routes.py           the three endpoints, JWT dependency</span></span>
<span class="line"><span>├── schemas.py          AskRequest · AskResponse · SearchRequest · Chunk</span></span>
<span class="line"><span>├── config.py           Config, from the environment; default prompts</span></span>
<span class="line"><span>├── services/</span></span>
<span class="line"><span>│   ├── retrieval.py      retrieve · answer_question · search_chunks</span></span>
<span class="line"><span>│   └── security.py       verify_jwt</span></span>
<span class="line"><span>├── clients/</span></span>
<span class="line"><span>│   ├── embeddings.py     encode(question) with the retrieval instruction</span></span>
<span class="line"><span>│   ├── translation.py    detect_language · translations · Marian models</span></span>
<span class="line"><span>│   ├── vectordb.py       search · count_chunks · read_payload (read-only)</span></span>
<span class="line"><span>│   └── llm.py            ask(prompt) through the OpenAI SDK</span></span>
<span class="line"><span>└── tools/make_jwt.py   a dev token signed with APP_SECRET</span></span></code></pre></div><p><img src="`+r+'" alt="Modules"></p></details><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/health</code></td></tr><tr><td><code>POST</code></td><td><code>/search</code></td></tr><tr><td><code>POST</code></td><td><code>/ask</code></td></tr></tbody></table><h3 id="post-search-semantic-search-only" tabindex="-1"><code>POST /search</code> : Semantic search only <a class="header-anchor" href="#post-search-semantic-search-only" aria-label="Permalink to &quot;`POST /search` : Semantic search only&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th style="text-align:center;">Required</th><th>Constraints</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td style="text-align:center;">✓</td><td>1–2000 characters</td><td>the question, in any language</td></tr><tr><td><code>top_k</code></td><td>integer</td><td style="text-align:center;"></td><td>1–50, default <code>5</code></td><td>how many passages to return</td></tr></tbody></table><p><img src="'+i+'" alt="POST /search"></p><h3 id="post-ask-retrieval-augmented-answer" tabindex="-1"><code>POST /ask</code> : Retrieval-augmented answer <a class="header-anchor" href="#post-ask-retrieval-augmented-answer" aria-label="Permalink to &quot;`POST /ask` : Retrieval-augmented answer&quot;">​</a></h3><p>the same retrieval as <code>/search</code> with <code>top_k = TOP_K</code>, then the LLM.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th style="text-align:center;">Required</th><th>Constraints</th><th>Description</th></tr></thead><tbody><tr><td><code>question</code></td><td>string</td><td style="text-align:center;">✓</td><td>1–2000 characters</td><td>the question, in any language</td></tr></tbody></table><p><img src="'+c+'" alt="POST /ask"></p><h2 id="multilingual-retrieval" tabindex="-1">Multilingual retrieval <a class="header-anchor" href="#multilingual-retrieval" aria-label="Permalink to &quot;Multilingual retrieval&quot;">​</a></h2><p>Retrieval works across languages thanks to two mechanisms:</p><p><img src="'+t+'" alt="Multilingual retrieval"></p><ol><li><strong>The embedding model is multilingual.</strong> <a href="https://huggingface.co/Qwen/Qwen3-Embedding-0.6B" target="_blank" rel="noreferrer">Qwen3-Embedding-0.6B</a> matches questions and passages with similar meanings, even in different languages.</li><li><strong>Query translation</strong> <a href="https://marian-nmt.github.io/" target="_blank" rel="noreferrer">Marian</a> model translate questions to bridge vocabulary gaps (e.g. « grappes » → clusters). The original query is always kept.</li></ol><h2 id="the-llm" tabindex="-1">The LLM <a class="header-anchor" href="#the-llm" aria-label="Permalink to &quot;The LLM&quot;">​</a></h2><p><code>/ask</code> uses the official <a href="https://github.com/openai/openai-python" target="_blank" rel="noreferrer">OpenAI Python SDK</a> and the <code>LLM_ENDPOINT</code> variable, supporting any provider compatible with the <a href="https://platform.openai.com/docs/api-reference/chat" target="_blank" rel="noreferrer">Chat Completions API</a> (<a href="https://docs.claude.com/en/api/openai-sdk" target="_blank" rel="noreferrer">Anthropic</a>, <a href="https://platform.openai.com/docs/models" target="_blank" rel="noreferrer">OpenAI</a>, <a href="https://docs.mistral.ai/api/" target="_blank" rel="noreferrer">Mistral</a> or local <a href="https://github.com/ollama/ollama/blob/main/docs/openai.md" target="_blank" rel="noreferrer">Ollama</a>).</p><p>Only three settings are needed: <code>LLM_ENDPOINT</code>, <code>LLM_MODEL</code> and <code>LLM_API_KEY</code>.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p><strong>Required</strong></p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>QDRANT_URL</code></td><td>Qdrant REST endpoint</td></tr><tr><td><code>QDRANT_COLLECTION_CODE</code></td><td>collection of the chunks, the one the job writes</td></tr><tr><td><code>EMBEDDING_MODEL</code></td><td>must be the job&#39;s, e.g. <code>Qwen/Qwen3-Embedding-0.6B</code></td></tr><tr><td><code>LLM_ENDPOINT</code></td><td>base URL of an OpenAI-compatible API</td></tr><tr><td><code>LLM_MODEL</code></td><td>chat model identifier</td></tr><tr><td><code>LLM_API_KEY</code></td><td>key for the provider</td></tr><tr><td><code>APP_SECRET</code></td><td>JWT signing secret, required unless <code>KNOWLEDGE_AUTH_ENABLED=false</code></td></tr></tbody></table><p><strong>Optional</strong></p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>QUERY_TRANSLATION_MODEL</code></td><td><em>(empty: off)</em></td><td>one Marian model name or several, comma-separated, see <a href="#multilingual-retrieval">Multilingual retrieval</a></td></tr><tr><td><code>LLM_PROMPT</code></td><td>the default system prompt above</td><td>system message of <code>/ask</code></td></tr><tr><td><code>TOP_K</code></td><td><code>6</code></td><td>passages retrieved for <code>/ask</code></td></tr><tr><td><code>MAX_CONTEXT_CHARS</code></td><td><code>14000</code></td><td>character budget of the context given to the LLM</td></tr><tr><td><code>MAX_ANSWER_TOKENS</code></td><td><code>1024</code></td><td><code>max_tokens</code> of the completion</td></tr><tr><td><code>KNOWLEDGE_AUTH_ENABLED</code></td><td><code>true</code></td><td>anything but <code>false</code> keeps authentication on</td></tr><tr><td><code>JWT_ALGORITHM</code></td><td><code>HS256</code></td><td>accepted signature algorithm</td></tr><tr><td><code>JWT_AUDIENCE</code> · <code>JWT_ISSUER</code></td><td><code>kalisio</code> · <code>kalisio</code></td><td>expected <code>aud</code> and <code>iss</code> claims</td></tr><tr><td><code>HOST</code> · <code>PORT</code></td><td><code>127.0.0.1</code> · <code>8187</code></td><td>binding; <code>0.0.0.0</code> in a container</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>INFO</code></td><td>verbosity of the <code>knowledge.*</code> loggers</td></tr><tr><td><code>APP_VERSION</code></td><td><code>0.1.0</code></td><td>version shown in the OpenAPI documentation</td></tr></tbody></table>',26)])])}const y=a(l,[["render",p]]);export{k as __pageData,y as default};
